 1	package shop.db;
 2	
 3	import java.sql.Connection;
 4	import java.sql.SQLException;
 5	import java.sql.Statement;
 6	import java.util.List;
 7	import javax.sql.DataSource;
 8	
 9	/** Creates the tables and the initial catalog. Safe to run on every start, from several instances at once. */
10	public final class Schema {
11	    private static final long LOCK_KEY = 7_272_018L;
12	
13	    private static final List<String> DDL = List.of(
14	            "CREATE TABLE IF NOT EXISTS products ("
15	                    + "sku VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, price NUMERIC(12,2) NOT NULL, "
16	                    + "weight_kg NUMERIC(10,2) NOT NULL, stock INTEGER NOT NULL CHECK (stock >= 0), "
17	                    + "discontinued BOOLEAN NOT NULL)",
18	            "CREATE TABLE IF NOT EXISTS customers ("
19	                    + "cpf VARCHAR(32) PRIMARY KEY, email VARCHAR(255) NOT NULL, "
20	                    + "credit_balance NUMERIC(12,2) NOT NULL DEFAULT 0)",
21	            "CREATE TABLE IF NOT EXISTS orders ("
22	                    + "id VARCHAR(36) PRIMARY KEY, cpf VARCHAR(32) NOT NULL, email VARCHAR(255) NOT NULL, "
23	                    + "status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, "
24	                    + "summary TEXT NOT NULL, tracking_code VARCHAR(255))",
25	            "CREATE INDEX IF NOT EXISTS idx_orders_cpf_status ON orders (cpf, status)",
26	            "CREATE TABLE IF NOT EXISTS order_items ("
27	                    + "order_id VARCHAR(36) NOT NULL REFERENCES orders (id), line_no INTEGER NOT NULL, "
28	                    + "sku VARCHAR(64) NOT NULL, quantity INTEGER NOT NULL, PRIMARY KEY (order_id, line_no))",
29	            "CREATE TABLE IF NOT EXISTS payment_events ("
30	                    + "order_id VARCHAR(36) NOT NULL, transaction_id VARCHAR(255) NOT NULL, "
31	                    + "outcome VARCHAR(32) NOT NULL, PRIMARY KEY (order_id, transaction_id))",
32	            "CREATE TABLE IF NOT EXISTS notifications ("
33	                    + "seq BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id VARCHAR(36) NOT NULL UNIQUE, "
34	                    + "cpf VARCHAR(32) NOT NULL, notif_type VARCHAR(32) NOT NULL, order_id VARCHAR(36) NOT NULL, "
35	                    + "status VARCHAR(8) NOT NULL)",
36	            "CREATE INDEX IF NOT EXISTS idx_notifications_cpf ON notifications (cpf)");
37	
38	    private static final String[][] CATALOG = {
39	            {"CAM-001", "Camiseta básica", "79.90", "0.30", "50", "false"},
40	            {"TEN-001", "Tênis corrida", "249.90", "1.20", "10", "false"},
41	            {"FON-001", "Fone sem fio", "199.90", "0.25", "5", "false"},
42	            {"MEI-001", "Meia esportiva", "19.90", "0.10", "100", "false"},
43	            {"JAQ-001", "Jaqueta corta-vento", "389.90", "0.80", "3", "false"},
44	            {"MOC-001", "Mochila urbana", "159.90", "0.90", "1", "false"},
45	            {"BON-001", "Boné aba reta", "59.90", "0.15", "0", "false"},
46	            {"REL-001", "Relógio digital", "129.90", "0.20", "8", "true"}};
47	
48	    private Schema() {
49	    }
50	
51	    public static void init(DataSource dataSource) throws SQLException {
52	        try (Connection c = dataSource.getConnection()) {
53	            c.setAutoCommit(true);
54	            boolean postgres = c.getMetaData().getDatabaseProductName().toLowerCase().contains("postgres");
55	            if (postgres) {
56	                // serializes concurrent starts of several instances
57	                try (Statement s = c.createStatement()) {
58	                    s.execute("SELECT pg_advisory_lock(" + LOCK_KEY + ")");
59	                }
60	            }
61	            try {
62	                try (Statement s = c.createStatement()) {
63	                    for (String ddl : DDL) {
64	                        s.execute(ddl);
65	                    }
66	                }
67	                seedCatalog(c);
68	            } finally {
69	                if (postgres) {
70	                    try (Statement s = c.createStatement()) {
71	                        s.execute("SELECT pg_advisory_unlock(" + LOCK_KEY + ")");
72	                    }
73	                }
74	            }
75	        }
76	    }
77	
78	    private static void seedCatalog(Connection c) throws SQLException {
79	        String sql = "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) "
80	                + "SELECT CAST(? AS VARCHAR(64)), CAST(? AS VARCHAR(255)), CAST(? AS NUMERIC(12,2)), "
81	                + "CAST(? AS NUMERIC(10,2)), CAST(? AS INTEGER), CAST(? AS BOOLEAN) "
82	                + "WHERE NOT EXISTS (SELECT 1 FROM products WHERE sku = ?)";
83	        try (var ps = c.prepareStatement(sql)) {
84	            for (String[] row : CATALOG) {
85	                ps.setString(1, row[0]);
86	                ps.setString(2, row[1]);
87	                ps.setBigDecimal(3, new java.math.BigDecimal(row[2]));
88	                ps.setBigDecimal(4, new java.math.BigDecimal(row[3]));
89	                ps.setInt(5, Integer.parseInt(row[4]));
90	                ps.setBoolean(6, Boolean.parseBoolean(row[5]));
91	                ps.setString(7, row[0]);
92	                ps.executeUpdate();
93	            }
94	        }
95	    }
96	}
 1	package shop.db;
 2	
 3	import java.sql.Connection;
 4	import java.sql.SQLException;
 5	import javax.sql.DataSource;
 6	
 7	public final class Database {
 8	    @FunctionalInterface
 9	    public interface Work<T> {
10	        T run(Dao dao) throws SQLException;
11	    }
12	
13	    private final DataSource dataSource;
14	
15	    private final boolean postgres;
16	
17	    public Database(DataSource dataSource) {
18	        this.dataSource = dataSource;
19	        try (Connection c = dataSource.getConnection()) {
20	            this.postgres = c.getMetaData().getDatabaseProductName().toLowerCase().contains("postgres");
21	        } catch (SQLException e) {
22	            throw new DbException(e);
23	        }
24	    }
25	
26	    /** Runs the work in one transaction: commits if it returns, rolls back if it throws. */
27	    public <T> T tx(Work<T> work) {
28	        try (Connection connection = dataSource.getConnection()) {
29	            connection.setAutoCommit(false);
30	            try {
31	                T result = work.run(new Dao(connection, postgres));
32	                connection.commit();
33	                return result;
34	            } catch (Throwable e) {
35	                try {
36	                    connection.rollback();
37	                } catch (SQLException suppressed) {
38	                    e.addSuppressed(suppressed);
39	                }
40	                throw e;
41	            }
42	        } catch (SQLException e) {
43	            throw new DbException(e);
44	        }
45	    }
46	}

