  1	package shop.db;
  2	
  3	import java.math.BigDecimal;
  4	import java.sql.Connection;
  5	import java.sql.PreparedStatement;
  6	import java.sql.ResultSet;
  7	import java.sql.SQLException;
  8	import java.time.OffsetDateTime;
  9	import java.time.ZoneOffset;
 10	import java.util.ArrayList;
 11	import java.util.Collection;
 12	import java.util.LinkedHashMap;
 13	import java.util.List;
 14	import java.util.Map;
 15	import java.util.Optional;
 16	import java.util.TreeSet;
 17	import shop.domain.Customer;
 18	import shop.domain.Json;
 19	import shop.domain.Money;
 20	import shop.domain.Notification;
 21	import shop.domain.NotificationType;
 22	import shop.domain.Order;
 23	import shop.domain.OrderItem;
 24	import shop.domain.OrderStatus;
 25	import shop.domain.Product;
 26	import shop.domain.Summary;
 27	
 28	/** All SQL of the service, bound to one transaction. */
 29	public final class Dao {
 30	    private static final String PRODUCT_COLUMNS = "sku, name, price, weight_kg, stock, discontinued";
 31	
 32	    private final Connection c;
 33	    private final boolean postgres;
 34	
 35	    Dao(Connection c, boolean postgres) {
 36	        this.c = c;
 37	        this.postgres = postgres;
 38	    }
 39	
 40	    // ---- products
 41	
 42	    public Optional<Product> product(String sku) throws SQLException {
 43	        try (PreparedStatement ps = c.prepareStatement("SELECT " + PRODUCT_COLUMNS + " FROM products WHERE sku = ?")) {
 44	            ps.setString(1, sku);
 45	            try (ResultSet rs = ps.executeQuery()) {
 46	                return rs.next() ? Optional.of(product(rs)) : Optional.empty();
 47	            }
 48	        }
 49	    }
 50	
 51	    public Map<String, Product> products(Collection<String> skus) throws SQLException {
 52	        Map<String, Product> result = new LinkedHashMap<>();
 53	        for (String sku : skus) {
 54	            product(sku).ifPresent(p -> result.put(sku, p));
 55	        }
 56	        return result;
 57	    }
 58	
 59	    /** Locks the rows in a fixed (sorted) order so concurrent transactions cannot deadlock. */
 60	    public Map<String, Product> lockProducts(Collection<String> skus) throws SQLException {
 61	        Map<String, Product> result = new LinkedHashMap<>();
 62	        for (String sku : new TreeSet<>(skus)) {
 63	            try (PreparedStatement ps = c.prepareStatement(
 64	                    "SELECT " + PRODUCT_COLUMNS + " FROM products WHERE sku = ? FOR UPDATE")) {
 65	                ps.setString(1, sku);
 66	                try (ResultSet rs = ps.executeQuery()) {
 67	                    if (rs.next()) {
 68	                        result.put(sku, product(rs));
 69	                    }
 70	                }
 71	            }
 72	        }
 73	        return result;
 74	    }
 75	
 76	    public void adjustStock(String sku, int delta) throws SQLException {
 77	        try (PreparedStatement ps = c.prepareStatement("UPDATE products SET stock = stock + ? WHERE sku = ?")) {
 78	            ps.setInt(1, delta);
 79	            ps.setString(2, sku);
 80	            ps.executeUpdate();
 81	        }
 82	    }
 83	
 84	    private static Product product(ResultSet rs) throws SQLException {
 85	        return new Product(rs.getString("sku"), rs.getString("name"), Money.round(rs.getBigDecimal("price")),
 86	                Money.round(rs.getBigDecimal("weight_kg")), rs.getInt("stock"), rs.getBoolean("discontinued"));
 87	    }
 88	
 89	    // ---- customers
 90	
 91	    public void ensureCustomer(String cpf, String email) throws SQLException {
 92	        // atomic "insert if absent" so that two service instances can race safely
 93	        String sql = postgres
 94	                ? "INSERT INTO customers (cpf, email, credit_balance) VALUES (?, ?, 0) ON CONFLICT (cpf) DO NOTHING"
 95	                : "INSERT INTO customers (cpf, email, credit_balance) SELECT CAST(? AS VARCHAR(32)), "
 96	                + "CAST(? AS VARCHAR(255)), 0 WHERE NOT EXISTS (SELECT 1 FROM customers WHERE cpf = ?)";
 97	        try (PreparedStatement ps = c.prepareStatement(sql)) {
 98	            ps.setString(1, cpf);
 99	            ps.setString(2, email);
100	            if (!postgres) {
101	                ps.setString(3, cpf);
102	            }
103	            ps.executeUpdate();
104	        }
105	    }
106	
107	    public Optional<Customer> customer(String cpf) throws SQLException {
108	        try (PreparedStatement ps = c.prepareStatement("SELECT cpf, credit_balance FROM customers WHERE cpf = ?")) {
109	            ps.setString(1, cpf);
110	            try (ResultSet rs = ps.executeQuery()) {
111	                return rs.next()
112	                        ? Optional.of(new Customer(rs.getString(1), Money.round(rs.getBigDecimal(2))))
113	                        : Optional.empty();
114	            }
115	        }
116	    }
117	
118	    public void addCredit(String cpf, BigDecimal delta) throws SQLException {
119	        try (PreparedStatement ps = c.prepareStatement(
120	                "UPDATE customers SET credit_balance = credit_balance + ? WHERE cpf = ?")) {
121	            ps.setBigDecimal(1, delta);
122	            ps.setString(2, cpf);
123	            ps.executeUpdate();
124	        }
125	    }
126	
127	    /** True when the customer has an order that is paid, shipped or delivered. */
128	    public boolean hasCompletedPurchase(String cpf) throws SQLException {
129	        try (PreparedStatement ps = c.prepareStatement(
130	                "SELECT 1 FROM orders WHERE cpf = ? AND status IN ('PAID', 'SHIPPED', 'DELIVERED')")) {
131	            ps.setString(1, cpf);
132	            try (ResultSet rs = ps.executeQuery()) {
133	                return rs.next();
134	            }
135	        }
136	    }
137	
138	    // ---- orders
139	
140	    public void insertOrder(Order o) throws SQLException {
141	        try (PreparedStatement ps = c.prepareStatement(
142	                "INSERT INTO orders (id, cpf, email, status, created_at, summary) VALUES (?, ?, ?, ?, ?, ?)")) {
143	            ps.setString(1, o.id());
144	            ps.setString(2, o.cpf());
145	            ps.setString(3, o.email());
146	            ps.setString(4, o.status().name());
147	            ps.setObject(5, OffsetDateTime.ofInstant(o.createdAt(), ZoneOffset.UTC));
148	            ps.setString(6, Json.write(o.summary()));
149	            ps.executeUpdate();
150	        }
151	        try (PreparedStatement ps = c.prepareStatement(
152	                "INSERT INTO order_items (order_id, line_no, sku, quantity) VALUES (?, ?, ?, ?)")) {
153	            int line = 0;
154	            for (OrderItem item : o.items()) {
155	                ps.setString(1, o.id());
156	                ps.setInt(2, line++);
157	                ps.setString(3, item.sku());
158	                ps.setInt(4, item.quantity());
159	                ps.executeUpdate();
160	            }
161	        }
162	    }
163	
164	    public Optional<Order> order(String id, boolean lock) throws SQLException {
165	        String sql = "SELECT id, cpf, email, status, created_at, summary, tracking_code FROM orders WHERE id = ?"
166	                + (lock ? " FOR UPDATE" : "");
167	        Order header;
168	        try (PreparedStatement ps = c.prepareStatement(sql)) {
169	            ps.setString(1, id);
170	            try (ResultSet rs = ps.executeQuery()) {
171	                if (!rs.next()) {
172	                    return Optional.empty();
173	                }
174	                header = new Order(rs.getString("id"), rs.getString("cpf"), rs.getString("email"),
175	                        OrderStatus.valueOf(rs.getString("status")),
176	                        rs.getObject("created_at", OffsetDateTime.class).toInstant(),
177	                        Json.read(rs.getString("summary"), Summary.class), null, rs.getString("tracking_code"));
178	            }
179	        }
180	        List<OrderItem> items = new ArrayList<>();
181	        try (PreparedStatement ps = c.prepareStatement(
182	                "SELECT sku, quantity FROM order_items WHERE order_id = ? ORDER BY line_no")) {
183	            ps.setString(1, id);
184	            try (ResultSet rs = ps.executeQuery()) {
185	                while (rs.next()) {
186	                    items.add(new OrderItem(rs.getString(1), rs.getInt(2)));
187	                }
188	            }
189	        }
190	        return Optional.of(new Order(header.id(), header.cpf(), header.email(), header.status(), header.createdAt(),
191	                header.summary(), items, header.trackingCode()));
192	    }
193	
194	    public void updateStatus(String id, OrderStatus status) throws SQLException {
195	        try (PreparedStatement ps = c.prepareStatement("UPDATE orders SET status = ? WHERE id = ?")) {
196	            ps.setString(1, status.name());
197	            ps.setString(2, id);
198	            ps.executeUpdate();
199	        }
200	    }
201	
202	    public void updateTrackingCode(String id, String trackingCode) throws SQLException {
203	        try (PreparedStatement ps = c.prepareStatement("UPDATE orders SET tracking_code = ? WHERE id = ?")) {
204	            ps.setString(1, trackingCode);
205	            ps.setString(2, id);
206	            ps.executeUpdate();
207	        }
208	    }
209	
210	    // ---- payment notices (idempotency)
211	
212	    public Optional<String> paymentOutcome(String orderId, String transactionId) throws SQLException {
213	        try (PreparedStatement ps = c.prepareStatement(
214	                "SELECT outcome FROM payment_events WHERE order_id = ? AND transaction_id = ?")) {
215	            ps.setString(1, orderId);
216	            ps.setString(2, transactionId);
217	            try (ResultSet rs = ps.executeQuery()) {
218	                return rs.next() ? Optional.of(rs.getString(1)) : Optional.empty();
219	            }
220	        }
221	    }
222	
223	    public void recordPaymentOutcome(String orderId, String transactionId, String outcome) throws SQLException {
224	        try (PreparedStatement ps = c.prepareStatement(
225	                "INSERT INTO payment_events (order_id, transaction_id, outcome) VALUES (?, ?, ?)")) {
226	            ps.setString(1, orderId);
227	            ps.setString(2, transactionId);
228	            ps.setString(3, outcome);
229	            ps.executeUpdate();
230	        }
231	    }
232	
233	    // ---- notifications
234	
235	    public void insertNotification(Notification n) throws SQLException {
236	        try (PreparedStatement ps = c.prepareStatement(
237	                "INSERT INTO notifications (id, cpf, notif_type, order_id, status) VALUES (?, ?, ?, ?, ?)")) {
238	            ps.setString(1, n.id());
239	            ps.setString(2, n.cpf());
240	            ps.setString(3, n.type().name());
241	            ps.setString(4, n.orderId());
242	            ps.setString(5, n.status());
243	            ps.executeUpdate();
244	        }
245	    }
246	
247	    public List<Notification> notifications(String cpf) throws SQLException {
248	        List<Notification> result = new ArrayList<>();
249	        try (PreparedStatement ps = c.prepareStatement(
250	                "SELECT id, cpf, notif_type, order_id, status FROM notifications WHERE cpf = ? ORDER BY seq")) {
251	            ps.setString(1, cpf);
252	            try (ResultSet rs = ps.executeQuery()) {
253	                while (rs.next()) {
254	                    result.add(notification(rs));
255	                }
256	            }
257	        }
258	        return result;
259	    }
260	
261	    public Optional<Notification> markRead(String id) throws SQLException {
262	        try (PreparedStatement ps = c.prepareStatement("UPDATE notifications SET status = 'READ' WHERE id = ?")) {
263	            ps.setString(1, id);
264	            ps.executeUpdate();
265	        }
266	        try (PreparedStatement ps = c.prepareStatement(
267	                "SELECT id, cpf, notif_type, order_id, status FROM notifications WHERE id = ?")) {
268	            ps.setString(1, id);
269	            try (ResultSet rs = ps.executeQuery()) {
270	                return rs.next() ? Optional.of(notification(rs)) : Optional.empty();
271	            }
272	        }
273	    }
274	
275	    private static Notification notification(ResultSet rs) throws SQLException {
276	        return new Notification(rs.getString(1), rs.getString(2), NotificationType.valueOf(rs.getString(3)),
277	                rs.getString(4), rs.getString(5));
278	    }
279	}
